invoke.src:
[Node: fromEventObservable(() =>
                interval(10).pipe(
                  map((value) => {
                    if (value === 5) {
                      throw new Error('some error');
                    }

                    return { type: 'COUNT', value };
                  })
                )
              )]

onError.guard:
[Node: ({ context, event }) => {
                  expect((event.error as any).message).toEqual('some error');
                  return (
                    context.count === 4 &&
                    (event.error as any).message === 'some error'
                  );
                }]
